parameters.responseBody:
={{ JSON.stringify({
  service: 'SnackCheck — Verificador de nutrición',
  description: 'Envía el código de barras de un alimento empaquetado y recibe un veredicto de salud en lenguaje claro, basado en datos reales de Open Food Facts.',
  method: 'POST',
  endpoint: '/webhook/nutrition-check',
  required_fields: { barcode: 'string numérico (EAN/UPC), p. ej. 3017620422003' },
  example_request: { barcode: '3017620422003' },
  responses: {
    '200 text/plain': 'Veredicto con titular, números clave 🔴/🟢 y párrafo amigable',
    '200 application/json': 'Esta ayuda, o aviso de datos de nutrición insuficientes',
    '400 application/json': 'Código de barras ausente o no numérico',
    '404 application/json': 'Producto no encontrado en Open Food Facts'
  }
}) }}

={{ JSON.stringify({
  error: 'invalid_barcode',
  message: ($json.body.barcode === undefined || $json.body.barcode === null || String($json.body.barcode).trim() === '')
    ? 'Falta el campo "barcode". Envía el código de barras del producto en el cuerpo de la solicitud.'
    : 'El campo "barcode" debe contener solo números (sin letras, espacios ni guiones).',
  received: $json.body.barcode ?? null,
  example: { barcode: '3017620422003' }
}) }}

={{ JSON.stringify({
  error: 'product_not_found',
  message: 'No encontramos ese código de barras en Open Food Facts. Revisa que esté completo o prueba con otro producto.',
  barcode: $('Set - Normalize Barcode').item.json.barcode,
  example: { barcode: '3017620422003' }
}) }}

