parameters.responseBody:
={{ JSON.stringify({
  status: 'insufficient_data',
  message: 'Encontramos el producto, pero no tiene datos de nutrición suficientes (azúcar, sal y grasa por 100 g) para darte un veredicto confiable.',
  product: { barcode: $json.barcode, name: $json.product_name, brands: $json.brands },
  missing_fields: [
    $json.sugars_100g === null || $json.sugars_100g === '' ? 'sugars_100g' : null,
    $json.salt_100g === null || $json.salt_100g === '' ? 'salt_100g' : null,
    $json.fat_100g === null || $json.fat_100g === '' ? 'fat_100g' : null
  ].filter(Boolean),
  tip: 'Puedes completar los datos del producto en openfoodfacts.org.'
}) }}

parameters.jsCode:
// Puntuación de preocupación = cuántos nutrientes quedaron en 'alto' (0–3).
// Cálculo sobre un solo ítem, sin bucles. Es una señal informativa:
// NO se usa para decidir el nivel del veredicto.
const sugarHigh = $json.sugar_level === 'alto' ? 1 : 0;
const saltHigh  = $json.salt_level  === 'alto' ? 1 : 0;
const fatHigh   = $json.fat_level   === 'alto' ? 1 : 0;

return { json: { ...$json, concern_score: sugarHigh + saltHigh + fatHigh } };

assignments.value:
={{ (() => {
  // Datos de la lógica + texto de la IA (que llega por el Merge en $json.text)
  const d = $('Set - Verdict Level (Worst Of Two)').item.json;
  const headline = {
    'saludable':    '✅ ¡Buena elección! — ' + d.product_name,
    'moderado':     '🟡 Bien, con moderación — ' + d.product_name,
    'no saludable': '⚠️ Mejor como gusto ocasional — ' + d.product_name
  }[d.verdict_level];
  const line = '─'.repeat(34);
  const row = (flag, label, value, unit, level) =>
    flag + ' ' + label.padEnd(9) + value.padStart(7) + ' ' + unit.padEnd(5) + (level ? '(' + level + ')' : '');
  const kcal = d.energy_kcal_100g === null || d.energy_kcal_100g === '' ? 's/d' : String(Math.round(Number(d.energy_kcal_100g)));
  return [
    headline,
    'Marca: ' + d.brands + ' · Nutri-Score: ' + (d.nutriscore_grade === 'unknown' ? 'sin dato' : d.nutriscore_grade.toUpperCase()),
    '',
    'Por cada 100 g',
    line,
    row(d.sugar_flag, 'Azúcar',  Number(d.sugars_100g).toFixed(1), 'g', d.sugar_level),
    row(d.salt_flag,  'Sal',     Number(d.salt_100g).toFixed(2),   'g', d.salt_level),
    row(d.fat_flag,   'Grasa',   Number(d.fat_100g).toFixed(1),    'g', d.fat_level),
    row('⚪', 'Energía', kcal, 'kcal', ''),
    line,
    'Nutrientes en alto: ' + d.concern_score + '/3',
    '',
    String($json.text || '').trim()
  ].join('\n');
})() }}
